unitsize(0.5 cm);

pair Z, W;

Z = 2*dir(34);
W = 5*dir(78);

draw(Circle((0,0),2),red);
draw(Circle((0,0),5),blue);
draw(Z--W);

dot("$z$", Z, SW);
dot("$w$", W, N);
[/asy]

